/**
 * @name Insecure use of low-level socket APIs with user-controlled host/port
 * @description Detects flows from remote input to socket.create_connection and asyncio.open_connection in aiohappyeyeballs
 * @kind path-problem
 * @problem.severity warning
 * @id py/aiohappyeyeballs/socket-user-input
 * @tags security
 *       external/cwe/cwe-020
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SocketConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("socket").getMember("create_connection").getACall() or
        call = API::moduleImport("asyncio").getMember("open_connection").getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module SocketFlow = TaintTracking::Global<SocketConfig>;
import SocketFlow::PathGraph

from SocketFlow::PathNode source, SocketFlow::PathNode sink
where SocketFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data flows into network connection target $@.", sink.getNode(), "target"

